# DynamoDB single-table access pattern key design (Python)
def make_order_item(user_id: str, created_iso: str, order_id: str, total: int) -> dict:
    return {
        'PK': f'USER#{user_id}',          # High-cardinality partition key
        'SK': f'ORDER#{created_iso}#{order_id}',  # Time-ordered range queries
        'total_cents': total,
    }
